CREATE TABLE submission_files (id BIGINT NOT NULL AUTO_INCREMENT,submission_id BIGINT NOT NULL,file_type VARCHAR(32) NOT NULL,original_name VARCHAR(255) NOT NULL,storage_key VARCHAR(500) NOT NULL,content_type VARCHAR(120) NOT NULL,size_bytes BIGINT NOT NULL,sha256 VARCHAR(64) NOT NULL,scan_status VARCHAR(24) NOT NULL,uploaded_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_submission_file_type(submission_id,file_type),CONSTRAINT fk_submission_file_submission FOREIGN KEY(submission_id) REFERENCES submissions(id));
CREATE TABLE submission_versions (id BIGINT NOT NULL AUTO_INCREMENT,submission_id BIGINT NOT NULL,version_number INT NOT NULL,snapshot_json LONGTEXT NOT NULL,change_source VARCHAR(30) NOT NULL,created_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_submission_version(submission_id,version_number),CONSTRAINT fk_submission_version_submission FOREIGN KEY(submission_id) REFERENCES submissions(id));
CREATE TABLE submission_deadlines (id BIGINT NOT NULL AUTO_INCREMENT,arena VARCHAR(190) NULL,deadline_at TIMESTAMP(6) NOT NULL,reason VARCHAR(1000) NOT NULL,updated_by BIGINT NOT NULL,updated_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),KEY idx_deadline_arena(arena),CONSTRAINT fk_deadline_admin FOREIGN KEY(updated_by) REFERENCES users(id));
ALTER TABLE submissions ADD COLUMN receipt_number VARCHAR(60) NULL;
CREATE UNIQUE INDEX uk_submission_receipt ON submissions(receipt_number);
